'use client';

import { useId } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ChevronRightIcon, InfoIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/registry/ndeko/ui/breadcrumb';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import {
  ARTICLE,
  CONTACT,
  RELATED,
  SECTIONS,
  SITE,
  type ArticleBlock,
} from './data';
import { FeedbackCard } from './feedback-card';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type FeedbackAction,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const CARD =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

function Block({ block }: { block: ArticleBlock }) {
  if (block.kind === 'steps') {
    return (
      <ol className='flex flex-col gap-3'>
        {block.items.map((item, index) => (
          <li key={item} className='flex items-start gap-3'>
            <span className='keycap-3d text-muted-foreground flex size-6 shrink-0 items-center justify-center rounded-md text-xs font-medium tabular-nums'>
              {index + 1}
            </span>
            <span className='pt-0.5 text-[15px] leading-6 text-pretty'>
              {item}
            </span>
          </li>
        ))}
      </ol>
    );
  }
  if (block.kind === 'note') {
    return (
      <p className='bg-info/10 flex items-start gap-3 rounded-xl px-4 py-3 text-[13px] leading-5'>
        <InfoIcon className='text-info-foreground mt-px size-4 shrink-0' />
        <span>
          {block.text}{' '}
          <a
            href={block.href}
            className={cn(
              'text-primary-ink rounded-sm font-medium underline-offset-4 hover:underline',
              FOCUS_RING
            )}
          >
            {block.linkLabel}
          </a>
        </span>
      </p>
    );
  }
  return <p className='text-[15px] leading-7 text-pretty'>{block.text}</p>;
}

export default function HelpCenter02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const relatedId = useId();
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;
  useKeptHeight(ref);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** The controls a person used leave with the question, so the focus follows to what replaced them. */
  function actAndFollow(action: FeedbackAction, selector: string) {
    act(action);
    focusLater(selector);
  }

  function answer(choice: 'yes' | 'no') {
    if (choice === 'no') {
      actAndFollow({ type: 'answered', answer: 'no' }, '[data-reason]');
      return;
    }
    actAndFollow({ type: 'answered', answer: 'yes' }, '[data-thanks]');
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-6 px-4 py-6 @2xl:px-8 @2xl:py-8'>
          <header className='flex min-h-8 items-center gap-2'>
            <a
              href={SITE.homeHref}
              className={cn(
                'flex items-center gap-2 rounded-md text-sm font-semibold',
                FOCUS_RING
              )}
            >
              <CompanyMark seed={SITE.name} size='lg' />
              {SITE.name}
            </a>
            <span className='text-muted-foreground text-sm'>Help</span>
            <span className='flex-1' />
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </header>

          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem>
                <BreadcrumbLink href={SITE.helpHref}>
                  Help center
                </BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                <BreadcrumbLink href={SITE.topicHref}>
                  {ARTICLE.topic}
                </BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator />
              <BreadcrumbItem className='min-w-0'>
                <BreadcrumbPage className='truncate'>
                  {ARTICLE.title}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>

          <div className='grid gap-10 @3xl:grid-cols-[minmax(0,1fr)_18rem] @3xl:gap-12'>
            <div className='flex min-w-0 flex-col gap-10'>
              <article className='flex flex-col gap-8'>
                <header className='flex flex-col gap-3'>
                  <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
                    {ARTICLE.title}
                  </h1>
                  <p className='text-muted-foreground text-xs tabular-nums'>
                    {ARTICLE.updated} · {ARTICLE.minutes} min read
                  </p>
                  <p className='text-muted-foreground text-base leading-7 text-pretty'>
                    {ARTICLE.lead}
                  </p>
                </header>
                {SECTIONS.map((section) => (
                  <section key={section.id} className='flex flex-col gap-4'>
                    <h2 className='text-lg font-semibold text-balance'>
                      {section.title}
                    </h2>
                    {section.blocks.map((block, index) => (
                      <Block key={`${section.id}-${index}`} block={block} />
                    ))}
                  </section>
                ))}
              </article>

              <FeedbackCard
                state={state}
                pressed={pressed}
                onAnswer={answer}
                onType={(value) => act({ type: 'typed', value })}
                onSend={() => actAndFollow({ type: 'sent' }, '[data-thanks]')}
                onSkip={() =>
                  actAndFollow({ type: 'skipped' }, '[data-thanks]')
                }
                onChange={() =>
                  actAndFollow({ type: 'changed' }, '[data-answer-yes]')
                }
              />
            </div>

            <aside className='flex flex-col gap-8'>
              <section
                aria-labelledby={relatedId}
                className='flex flex-col gap-2'
              >
                <h2 id={relatedId} className='px-1 text-[13px] font-medium'>
                  Related articles
                </h2>
                <ul className='flex flex-col'>
                  {RELATED.map((related) => (
                    <li key={related.id}>
                      <a
                        href={related.href}
                        className={cn(
                          'group hover:bg-foreground/[0.03] flex items-center gap-2 rounded-lg px-2 py-2 text-[13px] transition-colors duration-100',
                          FOCUS_RING
                        )}
                      >
                        <span className='min-w-0 flex-1 text-pretty'>
                          {related.title}
                        </span>
                        <ChevronRightIcon className='text-muted-foreground size-4 shrink-0 transition-transform duration-100 group-hover:translate-x-0.5' />
                      </a>
                    </li>
                  ))}
                </ul>
              </section>

              <section
                aria-label='Contact support'
                className={cn(CARD, 'flex flex-col gap-4 p-5')}
              >
                <div className='flex items-center gap-3'>
                  <Avatar seed={CONTACT.person} className='size-9' />
                  <div className='flex min-w-0 flex-col'>
                    <p className='text-[13px] font-medium'>Still stuck?</p>
                    <p className='text-muted-foreground text-xs'>
                      {CONTACT.person}, {CONTACT.role}
                    </p>
                  </div>
                </div>
                <p className='text-muted-foreground text-[13px] text-pretty'>
                  {CONTACT.lead}
                </p>
                <div className='flex flex-wrap gap-2'>
                  <Button
                    size='sm'
                    nativeButton={false}
                    render={<a href={CONTACT.chatHref} />}
                  >
                    Start a chat
                  </Button>
                  <Button
                    size='sm'
                    variant='outline'
                    nativeButton={false}
                    render={<a href={CONTACT.emailHref} />}
                  >
                    Email us
                  </Button>
                </div>
              </section>
            </aside>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useId } from 'react';

import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { ThumbsDownIcon, ThumbsUpIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import type { FeedbackState } from './session';

const REASON_LIMIT = 280;

function thanksLineOf(hasNote: boolean) {
  if (hasNote) {
    return 'Your note goes to the team that writes these articles, and someone reads every one.';
  }
  return 'Your answer helps us decide which articles to rewrite first.';
}

type FeedbackCardProps = {
  state: FeedbackState;
  pressed: string | null;
  onAnswer: (answer: 'yes' | 'no') => void;
  onType: (value: string) => void;
  onSend: () => void;
  onSkip: () => void;
  onChange: () => void;
};

export function FeedbackCard({
  state,
  pressed,
  onAnswer,
  onType,
  onSend,
  onSkip,
  onChange,
}: FeedbackCardProps) {
  const questionId = useId();
  const reasonId = useId();
  const isThanked = state.status === 'thanked';
  const isExplaining = state.status === 'explaining';
  const canSend = state.reason.trim() !== '';

  function send(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (canSend) {
      onSend();
    }
  }

  return (
    <section
      aria-labelledby={questionId}
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <AnimatedSize>
        {!isThanked && (
          <div className='flex flex-col gap-4'>
            <div className='flex flex-wrap items-center gap-3'>
              <h2 id={questionId} className='flex-1 text-sm font-medium'>
                Was this article helpful?
              </h2>
              <div className='flex items-center gap-2'>
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  data-answer-yes
                  onClick={() => onAnswer('yes')}
                  className={pressedQuietOf(pressed === 'answer-yes')}
                >
                  <ThumbsUpIcon className='size-3.5' />
                  Yes
                </Button>
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  aria-pressed={isExplaining}
                  onClick={() => onAnswer('no')}
                  className={cn(
                    'aria-pressed:bg-foreground/[0.06]',
                    pressedQuietOf(pressed === 'answer-no')
                  )}
                >
                  <ThumbsDownIcon className='size-3.5' />
                  No
                </Button>
              </div>
            </div>
            <Fold open={isExplaining}>
              <form onSubmit={send} className='flex flex-col gap-2 pb-0.5'>
                <label htmlFor={reasonId} className='text-[13px] font-medium'>
                  What was missing or wrong?
                </label>
                <Textarea
                  id={reasonId}
                  data-reason
                  rows={2}
                  maxLength={REASON_LIMIT}
                  placeholder='A sentence is enough'
                  value={state.reason}
                  onChange={(event) => onType(event.target.value)}
                />
                <div className='flex items-center gap-2'>
                  <Button
                    type='submit'
                    size='sm'
                    disabled={!canSend}
                    className={pressedSolidOf(pressed === 'send')}
                  >
                    Send
                  </Button>
                  <Button
                    type='button'
                    variant='ghost'
                    size='sm'
                    onClick={onSkip}
                  >
                    Skip
                  </Button>
                </div>
              </form>
            </Fold>
          </div>
        )}
        {isThanked && (
          <div className='flex items-start gap-3 transition-opacity duration-200 starting:opacity-0'>
            <StatusOrb tone='success' size='sm' />
            <div className='flex min-w-0 flex-col items-start gap-1'>
              <h2
                id={questionId}
                data-thanks
                tabIndex={-1}
                className={cn('rounded-sm text-sm font-medium', FOCUS_RING)}
              >
                Thanks for telling us
              </h2>
              <p className='text-muted-foreground text-[13px] text-pretty'>
                {thanksLineOf(state.hasNote)}
              </p>
              <button
                type='button'
                onClick={onChange}
                className={cn(
                  'text-primary-ink mt-1 rounded-sm text-xs font-medium underline-offset-4 hover:underline',
                  FOCUS_RING
                )}
              >
                Change my answer
              </button>
            </div>
          </div>
        )}
      </AnimatedSize>
    </section>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

export type Answer = 'none' | 'yes' | 'no';

export type FeedbackStatus = 'asking' | 'explaining' | 'thanked';

export type FeedbackState = {
  answer: Answer;
  status: FeedbackStatus;
  reason: string;
  /** True once a reason went out with the answer. */
  hasNote: boolean;
  spoken: string;
};

export type FeedbackAction =
  | { type: 'answered'; answer: 'yes' | 'no' }
  | { type: 'typed'; value: string }
  | { type: 'sent' }
  | { type: 'skipped' }
  | { type: 'changed' };

type Step = SessionStep<FeedbackState, FeedbackAction>;

export const INITIAL: FeedbackState = {
  answer: 'none',
  status: 'asking',
  reason: '',
  hasNote: false,
  spoken: '',
};

function answered(state: FeedbackState, answer: 'yes' | 'no'): FeedbackState {
  if (state.status === 'thanked') {
    return state;
  }
  if (answer === 'yes') {
    return {
      ...state,
      answer,
      status: 'thanked',
      hasNote: false,
      spoken: 'Thanks for letting us know',
    };
  }
  return { ...state, answer, status: 'explaining', spoken: '' };
}

function sent(state: FeedbackState): FeedbackState {
  if (state.status !== 'explaining') {
    return state;
  }
  const hasNote = state.reason.trim() !== '';
  if (!hasNote) {
    return state;
  }
  return {
    ...state,
    status: 'thanked',
    hasNote,
    spoken: 'Thanks, your note was sent to the team that writes these articles',
  };
}

function skipped(state: FeedbackState): FeedbackState {
  if (state.status !== 'explaining') {
    return state;
  }
  return {
    ...state,
    status: 'thanked',
    reason: '',
    hasNote: false,
    spoken: 'Thanks for letting us know',
  };
}

export function reducer(
  state: FeedbackState,
  action: FeedbackAction
): FeedbackState {
  switch (action.type) {
    case 'answered':
      return answered(state, action.answer);
    case 'typed':
      return { ...state, reason: action.value };
    case 'sent':
      return sent(state);
    case 'skipped':
      return skipped(state);
    case 'changed':
      return { ...INITIAL, spoken: 'Was this article helpful?' };
  }
}

const REASON = 'The steps for someone who already left are missing';

const KEY_MS = 40;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

/** A reader answers No, says what was missing and sends it; the question turns into a thank-you. */
export const SCRIPT: Step[] = [
  {
    after: 1800,
    by: 'demo',
    press: 'answer-no',
    action: { type: 'answered', answer: 'no' },
  },
  ...typing(REASON, 1100),
  { after: 700, by: 'demo', press: 'send', action: { type: 'sent' } },
];

/** Under reduced motion the reader has said what was missing and the thank-you stands in place. */
export const RESTING: FeedbackState = {
  answer: 'no',
  status: 'thanked',
  reason: REASON,
  hasNote: true,
  spoken: '',
};

export const LOOP_AFTER_MS = 3400;

